/**
 * Where Google Antigravity keeps its data, shared by the Antigravity usage,
 * session and new session code so they agree on the same folders. Owned by
 * the architect: implementers import these and do not edit this file (ask
 * the integrator).
 *
 * Antigravity comes as a desktop app (Antigravity.app), an IDE (Antigravity
 * IDE.app) and a CLI (agy). Each keeps its own data folder next to the
 * others under ~/.gemini; the two desktop programs also have an Electron
 * user-data folder. Everything here is read-only for the plugin.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { resolveDir } from '../kit';
import { PluginConfig } from '../types';

/** The three Antigravity programs: desktop app, CLI (agy), IDE. */
export type AntigravityProduct = 'app' | 'cli' | 'ide';

/** Data folder name of each product under antigravityRoot(). */
export const DATA_FOLDERS: Readonly<Record<AntigravityProduct, string>> = {
  app: 'antigravity',
  cli: 'antigravity-cli',
  ide: 'antigravity-ide',
};

/** Electron app name (user-data folder) of the desktop programs. */
export const APP_NAMES: Readonly<
  Record<Exclude<AntigravityProduct, 'cli'>, string>
> = {
  app: 'Antigravity',
  ide: 'Antigravity IDE',
};

/**
 * The folder holding the Antigravity data folders: the `antigravityDir`
 * setting, else ~/.gemini.
 */
export function antigravityRoot(
  config: PluginConfig | null | undefined,
  home: string = os.homedir()
): string {
  return resolveDir(
    config?.antigravityDir,
    undefined,
    path.join(home, '.gemini'),
    home
  );
}

/**
 * One product's data folder, e.g. ~/.gemini/antigravity-cli (conversations/,
 * brain/, conversation_summaries.db, …).
 */
export function antigravityDataDir(
  config: PluginConfig | null | undefined,
  product: AntigravityProduct,
  home: string = os.homedir()
): string {
  return path.join(antigravityRoot(config, home), DATA_FOLDERS[product]);
}

/**
 * The Electron user-data folder of the desktop app or the IDE (platform
 * default; no setting).
 */
export function antigravityUserDataDir(
  product: Exclude<AntigravityProduct, 'cli'>,
  platform: NodeJS.Platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
  home: string = os.homedir()
): string {
  const name = APP_NAMES[product];
  if (platform === 'darwin') {
    return path.join(home, 'Library', 'Application Support', name);
  }
  if (platform === 'win32') {
    return path.join(
      env.APPDATA || path.join(home, 'AppData', 'Roaming'),
      name
    );
  }
  return path.join(env.XDG_CONFIG_HOME || path.join(home, '.config'), name);
}

/** The `antigravityPath` setting as an absolute path, or null when not set. */
export function antigravityPathSetting(
  config: PluginConfig | null | undefined,
  home: string = os.homedir()
): string | null {
  const value = config?.antigravityPath;
  if (typeof value !== 'string' || !value.trim()) return null;
  return resolveDir(value, undefined, '', home);
}

/**
 * The products whose data folder exists under antigravityRoot(), in
 * DATA_FOLDERS order; [] when Antigravity has never run on this computer
 * (or the `antigravityDir` setting points elsewhere).
 */
export function installedProducts(
  config: PluginConfig | null | undefined,
  home: string = os.homedir()
): AntigravityProduct[] {
  return (Object.keys(DATA_FOLDERS) as AntigravityProduct[]).filter(product => {
    try {
      return fs
        .statSync(antigravityDataDir(config, product, home))
        .isDirectory();
    } catch {
      return false;
    }
  });
}
